 const group=e=>/^(내 캘린더의 설정|다른 캘린더의 설정|Settings for my calendars|Settings for other calendars)$/.test(accessible(e));
 for(const e of document.querySelectorAll('[role="treeitem"][aria-expanded="false"]'))if(group(e))e.click();
 const trees=[...document.querySelectorAll('[role="tree"]')].filter(group);
