 const account=[...document.querySelectorAll('[aria-label]')].map(accessible).find(s=>/Google 계정|Google Account/.test(s)&&s.includes('@'))||'';
 const email=(account.match(/[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/)||[''])[0];
 return {email,rows};
}

